export function buildCosmetics(){const themes=[['Moon','🌙'],['Lotus','🪷'],['Forest','🍃'],['River','🌊'],['Sunrise','☀️'],['Storm','⚡'],['Meadow','🌸'],['Crystal','💎'],['Mountain','⛰️'],['Autumn','🍂'],['Star','⭐']];const colors=[['Azure',140],['Lavender',210],['Rose',270],['Golden',35],['Scarlet',310],['Mint',15],['Teal',95],['Amber',325],['Violet',225],['Silver',170],['Emerald',0]];const out=[];for(const [theme,emblem] of themes)for(const [color,hue] of colors)for(const style of ['Hopper','Guardian']){const index=out.length;out.push({id:'collectible-'+index,name:`${color} ${theme} ${style}`,price:30+Math.floor((index+10)/9)*10+(index%9)*5,emblem,hue,style,collection:true});}return out;}
export function collectionPageUnlocked(profile,all,page){if(page===0)return true;const previous=all.slice((page-1)*9,page*9);return previous.length===9&&previous.every(f=>profile.owned.includes(f.id));}
export function highestCollectionPage(profile,all){let page=0;while(page<Math.ceil(all.length/9)-1&&collectionPageUnlocked(profile,all,page+1))page++;return page;}
